    return sorted((r-min(rs),c-min(cs)) for r,c in p)

def solve(i,o):
    H=len(i);W=len(i[0])
    marker=max(max(r) for r in i)
    seed=rel([(r,c) for r in range(H) for c in range(W) if i[r][c]==marker])
    out=[row[:] for row in i]
    hits=[]
    for dr in range(H):
        for dc in range(W):
            pts=[(r+dr,c+dc) for r,c in seed]
            if all(0<=r<H and 0<=c<W for r,c in pts) and all(i[r][c]==0 for r,c in pts):
                hits.append((dr,dc))
                for r,c in pts: out[r][c]=marker
    return out,hits

