from collections import Counter
def solve2(i):
    H=len(i);W=len(i[0])
    cnt=Counter(x for r in i for x in r)
    marker=min(cnt,key=cnt.get)  # rarest color
    seed=rel([(r,c) for r in range(H) for c in range(W) if i[r][c]==marker])
    out=[row[:] for row in i]; hits=[]
    for dr in range(H):
        for dc in range(W):
            pts=[(r+dr,c+dc) for r,c in seed]
            if all(0<=r<H and 0<=c<W for r,c in pts) and all(i[r][c]==0 for r,c in pts):
                hits.append((dr,dc))
                for r,c in pts: out[r][c]=marker
    return out,hits,marker
